from itertools import combinations
import heapq


def _quota_solver(capacity, tie):
    def solve(data):
        jobs = data['jobs']
        k = data['k']
        blocked = set(data.get('blocked', []))
        mandatory = set(data.get('mandatory', []))
        quotas = data.get('quotas', {})
        best_value = None
        best_ids = None

        if mandatory & blocked:
            return {'error': 'impossible'}
        options = [job for job in jobs if job['id'] not in blocked]
        for chosen in combinations(options, k):
            ids = {job['id'] for job in chosen}
            if not mandatory <= ids:
                continue
            counts = {}
            for job in chosen:
                group = job['group']
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue

            active = []
            valid = True
            for job in sorted(chosen, key=lambda row: (row['start'], row['end'])):
                while active and active[0] <= job['start']:
                    heapq.heappop(active)
                heapq.heappush(active, job['end'])
                if len(active) > capacity:
                    valid = False
                    break
            if not valid:
                continue

            value = sum(job['value'] for job in chosen)
            selected = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and
                     ((tie == 'largest' and selected > best_ids) or
                      (tie == 'smallest' and selected < best_ids)))):
                best_value, best_ids = value, selected

        if best_value is None:
            return {'error': 'impossible'}
        return {'selected': best_ids, 'value': best_value}
    return solve


def _component_06(data):
    cutoff = data.get('cutoff', 10**9)
    winners = {}
    for position, event in enumerate(data['events']):
        if event.get('sequence', 0) > cutoff:
            continue
        event_id = event.get('id', 'anonymous:' + str(position))
        key = (event.get('revision', 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get('opening', {}))

    def rounded(numerator, denominator, mode):
        if mode == 'half_up':
            return (2 * numerator + denominator) // (2 * denominator)
        return numerator // denominator

    for _, event in winners.values():
        if event.get('void', False):
            continue
        raw = event['price'] * event.get('quantity', 1)
        discount = min(10000, max(0, event.get('discount_bp', 0)))
        mode = data['rounding']
        net = rounded(raw * (10000 - discount), 10000, mode)
        tax = rounded(raw * event.get('tax_bp', 0), 10000, mode)
        total = net + tax
        if event.get('kind') == 'refund':
            total = -total
        key = event.get('account', 'default') + '|' + event.get('currency', 'USD')
        balances[key] = balances.get(key, 0) + total
    return {'balances': balances}


def _component_07(data):
    packages = data['packages']
    names = sorted(packages, reverse=True)
    features = set(data.get('features', []))
    blocked = data.get('blocked', {})
    pins = data.get('pins', {})
    constraints = {name: [tuple(bounds)] for name, bounds in data['roots'].items()}
    best_vector = None
    best_assignment = None

    def cyclic(edges):
        state = {}

        def visit(name):
            if state.get(name) == 1:
                return True
            if state.get(name) == 2:
                return False
            state[name] = 1
            for other in edges.get(name, ()):
                if visit(other):
                    return True
            state[name] = 2
            return False

        return any(visit(name) for name in edges if state.get(name, 0) == 0)

    def search(assignment, required, edges):
        nonlocal best_vector, best_assignment
        for name, version in assignment.items():
            if any(not low <= version <= high for low, high in required[name]):
                return
        pending = [name for name in required if name not in assignment]
        if not pending:
            if cyclic(edges):
                return
            vector = tuple(assignment.get(name, -1) for name in names)
            if best_vector is None or vector < best_vector:
                best_vector = vector
                best_assignment = dict(assignment)
            return

        name = min(pending, key=lambda n: sum(
            1 for row in packages.get(n, [])
            if all(low <= row['version'] <= high for low, high in required[n])
            and row['version'] not in blocked.get(n, [])
            and (n not in pins or row['version'] == pins[n])))
        for row in packages.get(name, []):
            version = row['version']
            if version in blocked.get(name, []):
                continue
            if name in pins and version != pins[name]:
                continue
            if not all(low <= version <= high for low, high in required[name]):
                continue
            next_assignment = dict(assignment)
            next_assignment[name] = version
            next_required = {key: list(value) for key, value in required.items()}
            deps = [dep for dep in row.get('deps', [])
                    if not dep.get('feature') or dep['feature'] in features]
            next_edges = {key: list(value) for key, value in edges.items()}
            next_edges[name] = []
            for dep in deps:
                dep_name = dep['name']
                next_edges[name].append(dep_name)
                next_required.setdefault(dep_name, []).append((dep['min'], dep['max']))
            search(next_assignment, next_required, next_edges)

    search({}, constraints, {})
    if best_assignment is None:
        return {'error': 'unsatisfiable'}
    return {'versions': best_assignment}


def _component_08(data):
    required = data.get('required', [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = bit.get(data['source'], 0)
    start_state = (data['source'], initial_mask, data['coupons'])
    distances = {start_state: data['start']}
    queue = [(data['start'], data['source'], initial_mask, data['coupons'])]
    graph = [[] for _ in range(data['n'])]
    for edge in data['edges']:
        graph[edge['u']].append(edge)

    while queue:
        time, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if distances.get(state) != time:
            continue
        if node == data['target'] and mask == full:
            return {'arrival': time}
        for edge in graph[node]:
            depart = max(time, edge['open'])
            if depart >= edge['close']:
                continue
            options = [(edge['duration'], coupons)]
            if coupons:
                options.append((max(1, edge['duration'] - edge.get('discount', 0)), coupons - 1))
            next_mask = mask | bit.get(edge['v'], 0)
            for duration, remaining in options:
                arrival = depart + duration
                if arrival > data['deadline']:
                    continue
                next_state = (edge['v'], next_mask, remaining)
                if arrival < distances.get(next_state, float('inf')):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, edge['v'], next_mask, remaining))
    return {'arrival': None}


SOLVERS = {
    'component_01': _quota_solver(1, 'largest'),
    'component_02': _quota_solver(2, 'largest'),
    'component_03': _quota_solver(1, 'smallest'),
    'component_04': _quota_solver(2, 'smallest'),
    'component_05': _quota_solver(1, 'largest'),
    'component_06': _component_06,
    'component_07': _component_07,
    'component_08': _component_08,
}
